<set-variable name="request-timeout" value="@{
    var models = context.Variables.GetValueOrDefault("config-models");
    var timeoutSettings = context.Variables.GetValueOrDefault("config-timeout-settings");
    var model = context.Variables.GetValueOrDefault("requestedModel", "");
    var streaming = context.Variables.GetValueOrDefault("is-streaming", false);

    // Get model-specific timeout (fallback to 120 if not configured)
    var modelConfig = models?[model];
    var baseTimeout = modelConfig?["timeout"]?.Value() ?? 120;

    // Apply streaming multiplier if applicable
    if (streaming) {
        var multiplier = timeoutSettings?["streaming-multiplier"]?.Value() ?? 3;
        return baseTimeout * multiplier;
    }
    return baseTimeout;
}" />
